.search-action,.search-input{
margin-bottom:-8px
}
.search form{
margin-bottom:8px
}
body.item-view .subscribe-section-container{
margin:5px 0 0 0;
width:100%
}
#page_body.section div.widget.FeaturedPost,div.widget.PopularPosts{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container .post-outer{
padding:0
}
.post:first-child{
margin:0
}
.post-body .snippet-thumbnail{
margin:0 3vw 3vw 0
}
.post-body .snippet-thumbnail img{
height:20vw;
width:20vw;
max-height:128px;
max-width:128px
}
div.widget.PopularPosts div.item-thumbnail{
margin:0 3vw 3vw 0
}
div.widget.PopularPosts div.item-thumbnail img{
height:20vw;
width:20vw;
max-height:88px;
max-width:88px
}
.post-title{
line-height:1
}
.post-title,.post-title a{
font-size:20px
}
#page_body.section div.widget.FeaturedPost h3 a{
font-size:22px
}
.mobile-ad .inline-ad{
display:block
}
.page_body.has-vertical-ads .vertical-ad-container,.page_body.has-vertical-ads .vertical-ad-container ins{
display:none
}
.page_body.has-vertical-ads .centered .centered-bottom,.page_body.has-vertical-ads .centered .centered-top{
display:block;
width:auto
}
div.post-filter-message div{
padding:8px 16px
}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
body{
position:relative
}
body.item-view .blog-name{
margin-left:48px
}
.page_body{
margin-left:$(sidebar.width)
}
.search{
margin-left:0
}
.search.focused{
width:100%
}
.sticky{
padding-left:$(sidebar.width)
}
.hamburger-menu{
display:none
}
body.collapsed-header .page_body .centered-top-container{
padding-left:$(sidebar.width);
padding-right:0;
width:100%
}
body.collapsed-header .centered-top-container .search.focused{
width:100%
}
body.collapsed-header .centered-top-container .blog-name{
margin-left:0
}
body.collapsed-header.item-view .centered-top-container .search.focused{
width:calc(100% - 50px)
}
body.collapsed-header.item-view .centered-top-container .blog-name{
margin-left:40px
}
}

/* ===== ToolPivio design overrides ===== */

/* ToolPivio visual layer — keeps Contempo's native Blog1 renderer intact. */
:root{--tp-ink:#12283e;--tp-muted:#526579;--tp-teal:#087f75;--tp-line:#dae4e9;--tp-paper:#f5f8fa}
html,body{margin:0!important;min-height:100%;background:var(--tp-paper)!important;color:var(--tp-ink)!important;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif!important}
body{overflow-x:hidden}
body .page{width:100%!important;max-width:none!important;min-height:0!important;background:transparent!important;margin:0!important;padding:0!important;overflow:visible!important}
body .page_body{margin:0!important;width:100%!important;max-width:none!important;padding:0!important;min-height:0!important;}
body .page_body .centered{max-width:none!important;margin:0!important;padding:0!important;min-height:0!important;display:block!important}
body .bg-photo,body .bg-photo-container,body .bg-photo-overlay,body .centered-top-container,body .centered-top-placeholder,body .sidebar-container,body .vertical-ad-container,body .page_body #footer{display:none!important}
body .page_body main#main{display:block!important;box-sizing:border-box!important;float:none!important;width:100%!important;max-width:none!important;min-height:0!important;margin:0!important;padding:0!important;position:relative!important;background:var(--tp-paper)!important}
body .tp-wrap{width:min(1120px,calc(100% - 40px));margin:0 auto}
body .tp-header{background:#fff;position:relative;z-index:50;border-bottom:1px solid var(--tp-line);font-family:system-ui,-apple-system,"Segoe UI",sans-serif}
body .tp-nav{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:86px;flex-wrap:wrap}
body a.tp-brand{font-size:25px;font-weight:850;color:var(--tp-ink)!important;text-decoration:none;letter-spacing:-1px}
body .tp-brand span{color:var(--tp-teal)}
body .tp-links{display:flex;align-items:center;gap:28px;flex-wrap:wrap}
body .tp-links a{font-size:14px;font-weight:700;color:var(--tp-ink)!important;text-decoration:none}
body .tp-links a:hover{color:var(--tp-teal)!important}
body .tp-hero{padding:74px 0 58px;background:linear-gradient(120deg,#eaf6f2,#f5f8fa 70%)}
body .tp-eyebrow{font-size:12px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:var(--tp-teal);margin:0 0 20px}
body .tp-hero h1{font-size:clamp(36px,5.3vw,64px);line-height:1.12;letter-spacing:-2px;max-width:800px;margin:18px 0 24px;color:var(--tp-ink)}
body .tp-hero h1 span{color:var(--tp-teal)}
body .tp-lead{font-size:19px;color:var(--tp-muted);max-width:650px;line-height:1.7}
body .tp-trust{display:flex;gap:24px;flex-wrap:wrap;font-size:13px;color:var(--tp-muted);margin-top:34px}
body .tp-catalog{padding:50px 0 70px}
body .tp-catalog-top{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}
body .tp-catalog h2{font-size:28px;letter-spacing:-.5px;line-height:1.25;color:var(--tp-ink);margin:8px 0 12px}
body .tp-search{width:min(100%,340px);display:block!important;float:none!important;margin:0!important;position:static!important;border:0!important;height:auto!important;line-height:normal!important}
body .tp-search label{display:block;font-size:14px;color:var(--tp-ink);font-weight:700;margin-bottom:7px}
body .tp-search input,body .tp-calculator input,body .tp-calculator select{display:block;width:100%;box-sizing:border-box;padding:12px 14px;border:1px solid #9cadba;border-radius:9px;background:white;color:var(--tp-ink);font:inherit;outline-offset:3px}
body .tp-filters{display:flex;gap:8px;flex-wrap:wrap;margin:26px 0}
body .tp-filters button{border:1px solid var(--tp-line);background:#fff;color:var(--tp-ink);padding:10px 14px;border-radius:30px;font:600 13px system-ui;cursor:pointer}
body .tp-filters button[aria-pressed=true]{background:var(--tp-ink);color:#fff;border-color:var(--tp-ink)}
body .tp-status{color:var(--tp-muted);font-size:14px;margin:8px 0 20px}
body .tp-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
body .tp-card{background:#fff;border:1px solid var(--tp-line);border-radius:16px;padding:26px;display:flex;flex-direction:column;align-items:flex-start;min-height:218px;box-shadow:0 6px 20px #12283e04}
body .tp-card:hover{border-color:#72b8ad}
body .tp-icon{background:#e5f4ef;color:var(--tp-teal);border-radius:12px;width:52px;height:52px;display:grid;place-items:center;font-size:24px;font-weight:700}
body .tp-card .tp-tag{font-size:11px;letter-spacing:.8px;text-transform:uppercase;color:var(--tp-teal);margin:18px 0 5px}
body .tp-card h3{color:var(--tp-ink);font-size:19px;line-height:1.3;margin:0 0 6px}
body .tp-card p:not(.tp-tag){color:var(--tp-muted);font-size:14px;line-height:1.5;margin:0 0 16px}
body .tp-card a{font-weight:750;font-size:14px;color:var(--tp-teal)!important;margin-top:auto}
body .tp-note{padding:28px;border:1px solid var(--tp-line);border-radius:14px;background:#edf4f5;margin-top:35px}
body .tp-note h2{margin:0 0 10px}body .tp-note p{color:var(--tp-muted);margin:8px 0}
body .tp-empty{padding:25px;border:1px dashed #9cadba;border-radius:12px}
body .tp-footer{background:var(--tp-ink)!important;color:#d7e3ed!important;padding:40px 0;font-size:13px;min-height:150px}
body .tp-footer .tp-footer-row{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap}
body .tp-footer a{color:#d7e3ed!important}
body .tp-footer .tp-brand{color:white!important}
body .tp-footer p{margin:12px 0;color:#d7e3ed}
body .tp-footer-links{display:flex;gap:18px;flex-wrap:wrap;align-items:flex-start}
body .tp-footer-links a{color:#d7e3ed!important;text-decoration:underline;text-underline-offset:4px}
/* Native Blogger page rendering: Blog1 comes from untouched working Contempo. */
body #page_body{width:min(960px,calc(100% - 40px))!important;max-width:none!important;margin:48px auto 72px!important;padding:0!important;display:block!important;background:transparent!important}
body #page_body .Blog{background:transparent!important}
body #page_body .Blog .blog-posts .post-outer-container{background:#fff!important;border:1px solid var(--tp-line);border-radius:16px;padding:35px 42px!important;margin:0 0 20px!important;box-shadow:0 8px 22px #12283e08;max-width:none!important}
body #page_body .post-outer{padding:0!important}
body #page_body .post-title,body #page_body .post-title a{font:750 clamp(28px,3.2vw,42px)/1.2 system-ui,-apple-system,"Segoe UI",sans-serif!important;letter-spacing:-.6px;color:var(--tp-ink)!important;float:none!important;max-width:none!important;margin:0 0 15px!important}
body #page_body .post-body{color:var(--tp-ink)!important;font:16px/1.75 system-ui,-apple-system,"Segoe UI",sans-serif!important;display:block!important;word-break:normal!important;margin:16px 0 25px!important}
body #page_body .post-body h2{font-size:26px;line-height:1.3;color:var(--tp-ink)!important;margin:22px 0 8px}
body #page_body .post-body p{margin:10px 0 16px}
body #page_body .post-body a{color:var(--tp-teal)!important}
body #page_body .post-body img,body #page_body .post-body iframe{max-width:100%;height:auto}
body #page_body .post-body [data-tool]{width:100%}
body .tp-calculator{padding:28px;background:#fff;border:1px solid var(--tp-line);border-radius:16px;margin:24px 0}
body .tp-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
body .tp-fields label{display:block;font-size:14px;font-weight:700;margin:0 0 7px}
body .tp-actions{display:flex;gap:12px;margin-top:24px}
body .tp-actions button{padding:11px 22px;border-radius:8px;border:1px solid var(--tp-teal);cursor:pointer;font-weight:700}
body .tp-primary{background:var(--tp-teal);color:#fff}
body .tp-secondary{background:#fff;color:var(--tp-teal)}
body .tp-result{background:#eaf6f2;color:var(--tp-ink);padding:20px;border-radius:10px;margin-top:24px;white-space:pre-line}
body .tp-error{color:#a02020;font-weight:700}
body .tp-calculator .tp-small{font-size:12px;color:var(--tp-muted)}
body .tp-post-quiet .post-footer,body .tp-post-quiet .post-share-buttons,body .tp-post-quiet .byline,body .tp-post-quiet #comments{display:none!important}
body [hidden]{display:none!important}
@media(max-width:760px){body .tp-cards{grid-template-columns:1fr}body .tp-wrap{width:calc(100% - 32px)}body .tp-nav{padding:16px 0;gap:10px}body .tp-hero{padding:48px 0 32px}body .tp-fields{grid-template-columns:1fr}body .tp-links{gap:16px}body #page_body{width:calc(100% - 24px)!important;margin:20px auto 40px!important}body #page_body .Blog .blog-posts .post-outer-container{padding:22px 18px!important}body .tp-card{min-height:0}body .tp-catalog{padding:38px 0 45px}}
@media(prefers-reduced-motion:no-preference){html{scroll-behavior:smooth}}


