head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}

body.script:
//<![CDATA[

/* ToolPivio calculators run locally in the browser. */
(function(root){'use strict';
 function number(value,positive){if((typeof value!=='string'&&typeof value!=='number')||String(value).trim()==='')throw Error('Enter every required value.');var n=Number(value);if(!Number.isFinite(n)||n<0||(positive&&n===0))throw Error(positive?'Enter a number greater than zero.':'Enter zero or more.');return n;}
 function finite(obj){if(Object.values(obj).some(v=>!Number.isFinite(v)))throw Error('These values are too large or too small.');return obj;}
 root.ToolPivioMath={roas:function(revenue,spend){revenue=number(revenue);spend=number(spend,true);return finite({roas:revenue/spend,percentage:revenue/spend*100});},margin:function(revenue,cost){revenue=number(revenue,true);cost=number(cost);return finite({profit:revenue-cost,margin:(revenue-cost)/revenue*100});},dpi:function(width,height,pw,ph,unit){width=number(width,true);height=number(height,true);pw=number(pw,true);ph=number(ph,true);if(!Number.isInteger(width)||!Number.isInteger(height))throw Error('Pixel dimensions must be whole numbers.');if(!['in','cm'].includes(unit))throw Error('Choose inches or centimeters.');var factor=unit==='cm'?2.54:1;return finite({horizontal:width/pw*factor,vertical:height/ph*factor});}};
})(window);
(function(){'use strict';
var definitions={roas:{fields:[['revenue','Attributed revenue','5000'],['spend','Advertising spend','1000']],calculate:function(v){var r=ToolPivioMath.roas(v.revenue,v.spend);return 'Return on ad spend: '+fmt(r.roas)+'×\nROAS percentage: '+fmt(r.percentage)+'%';}},margin:{fields:[['revenue','Revenue','100'],['cost','Total cost','60']],calculate:function(v){var r=ToolPivioMath.margin(v.revenue,v.cost);return 'Profit (in your input currency): '+fmt(r.profit)+'\nProfit margin: '+fmt(r.margin)+'%';}},dpi:{fields:[['width','Image width (pixels)','3000'],['height','Image height (pixels)','2400'],['printWidth','Print width','10'],['printHeight','Print height','8']],calculate:function(v){var r=ToolPivioMath.dpi(v.width,v.height,v.printWidth,v.printHeight,v.unit);return 'Horizontal resolution: '+fmt(r.horizontal)+' PPI\nVertical resolution: '+fmt(r.vertical)+' PPI';}}};
function fmt(n){return new Intl.NumberFormat('en',{maximumFractionDigits:2}).format(n);}
document.querySelectorAll('[data-tool]').forEach(function(host,index){var definition=definitions[host.dataset.tool];if(!definition)return;var form=document.createElement('form');form.className='tp-calculator';form.noValidate=true;form.innerHTML='<div class="tp-fields">'+definition.fields.map(function(f){return '<div><label for="calc-'+index+'-'+f[0]+'">'+f[1]+'</label><input id="calc-'+index+'-'+f[0]+'" name="'+f[0]+'" type="number" inputmode="decimal" step="any" min="0" required="required" placeholder="e.g. '+f[2]+'" /></div>';}).join('')+(host.dataset.tool==='dpi'?'<div><label for="unit-'+index+'">Print size unit</label><select id="unit-'+index+'" name="unit"><option value="in">Inches</option><option value="cm">Centimeters</option></select></div>':'')+'</div><p class="tp-error" role="alert"></p><div class="tp-actions"><button class="tp-primary" type="submit">Calculate</button><button class="tp-secondary" type="reset">Reset</button></div><div class="tp-result" role="status" aria-live="polite" hidden="hidden"></div><p class="tp-small">Results rounded to two decimal places.</p>';
var result=form.querySelector('.tp-result'),error=form.querySelector('.tp-error');form.addEventListener('submit',function(event){event.preventDefault();error.textContent='';result.hidden=true;try{result.textContent=definition.calculate(Object.fromEntries(new FormData(form)));result.hidden=false;}catch(e){error.textContent=e.message;}});form.addEventListener('input',function(){result.hidden=true;error.textContent='';});form.addEventListener('reset',function(){result.hidden=true;result.textContent='';error.textContent='';});host.appendChild(form);});
})();

